import{_ as t,o as a,c as i,ae as o}from"./chunks/framework.vXWZTEWX.js";const h=JSON.parse('{"title":"ADR 032: UI Design System & Theming Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"adr/032-ui-design-system.md","filePath":"adr/032-ui-design-system.md"}'),s={name:"adr/032-ui-design-system.md"};function n(r,e,l,d,c,g){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-032-ui-design-system-theming-strategy" tabindex="-1">ADR 032: UI Design System &amp; Theming Strategy <a class="header-anchor" href="#adr-032-ui-design-system-theming-strategy" aria-label="Permalink to &quot;ADR 032: UI Design System &amp; Theming Strategy&quot;">​</a></h1><p>Date: 2026-03-04</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The application required a professional, trustworthy aesthetic suitable for legal and corporate environments (Tender Analysis). The initial design was functional but lacked a cohesive identity. We needed to support both Light and Dark modes while maintaining sufficient contrast and visual hierarchy.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have implemented a custom <strong>Design System</strong> using Tailwind CSS, characterized by:</p><ol><li><p><strong>Color Palette</strong>:</p><ul><li><strong>Light Mode</strong>: Based on &quot;Crema&quot; tones (<code>#D3D0C2</code>, <code>#F5F4F0</code>) for backgrounds, paired with <code>Brand Gris</code> (<code>#374151</code>) for text to reduce eye strain compared to pure black.</li><li><strong>Dark Mode</strong>: Uses &quot;Charcoal&quot; (<code>#242B33</code>) and &quot;Gunmetal&quot; (<code>#1a1f24</code>) for a modern, deep aesthetic without the harshness of pure black (<code>#000000</code>).</li><li><strong>Accents</strong>: &quot;Gold&quot; (<code>#C5A028</code>) for primary highlights (Trust/Premium feel) and &quot;Emerald&quot; (<code>#10b981</code>) for success states.</li></ul></li><li><p><strong>Typography</strong>:</p><ul><li><strong>Headings</strong>: <em>Playfair Display</em> (Serif) to convey authority and tradition.</li><li><strong>Body</strong>: <em>Inter</em> (Sans-serif) for high readability in dense text (analysis results).</li></ul></li><li><p><strong>Theming Engine</strong>:</p><ul><li>Utilizes Tailwind&#39;s <code>darkMode: &#39;class&#39;</code> strategy.</li><li>State managed via React Context (<code>ThemeContext</code>), persisting user preference in <code>localStorage</code>.</li><li>Components are built with semantic color tokens (e.g., <code>text-brand-gris dark:text-gray-100</code>) rather than hardcoded hex values.</li></ul></li><li><p><strong>Visual Effects</strong>:</p><ul><li><strong>Glassmorphism</strong>: Used in cards and overlays (<code>bg-white/30 backdrop-blur-md</code>) to create depth.</li><li><strong>Soft Shadows</strong>: Custom shadow utilities to lift elements subtly off the background.</li></ul></li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Consistency</strong>: All components now share a unified look and feel.</li><li><strong>Maintainability</strong>: Global changes can be made by updating the Tailwind configuration.</li><li><strong>Accessibility</strong>: High contrast ratios are maintained in both modes (checked via WCAG standards).</li><li><strong>Development Speed</strong>: Utility-first CSS allows for rapid iteration without fighting stylesheet specificity.</li></ul>',11)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
